# Initially generated by GitHub Copilot.
"""Polite HTTP downloading utilities.

THE SPACING A POLITEDOWNLOADER GUARANTEES

Every request that a PoliteDownloader sends to a host starts at least the delay that its
ThrottleConfig gives, never less than min_delay_s, after the latest request to that host
started.  That covers every first attempt and every retry, every robots.txt read, and
every hop of a redirect.  The downloader follows a redirect itself, one hop at a time:
it sends a hop only once the throttle allows it and, when robots.txt is obeyed, only
once the robots.txt of the hop's target allows it.

A request starts when the throttle lets it go, just before the downloader hands it to
its requests session, and its start is the clock's reading then, after any wait.  The
latest request is the latest that any PoliteDownloader in the process sent, on the same
clock.  Downloaders share one record of request starts for each monotonic_fun, and
every downloader not given a monotonic_fun of its own uses time.monotonic, so the first
request of a second downloader waits for the first downloader's last request to that
host.  A host is a URL's hostname, in lowercase: http://example.org/ and
https://example.org:8443/ have one host, and https://archive.org/ and
https://web.archive.org/ have two.  A lock makes the record safe for threads; a thread
holds it while it waits, so threads that request different hosts still wait for each
other.

WHERE THE GUARANTEE STOPS

1. At the process.  Nothing spaces a request from the requests of another process, such
   as an earlier run of the same script that ended a moment ago.
2. At PoliteDownloader.  A request sent any other way, for example straight through the
   requests session that a downloader was given, is neither spaced nor recorded.
3. At each downloader's own delay.  If downloader A's delay is 5 seconds and downloader
   B's is 1.5 seconds, B's request may start 1.5 seconds after A's request to the same
   host.
4. At the clock.  Downloaders given different monotonic_fun keep separate records.
5. At the session.  A request reaches its host a little after it starts: requests
   must send it, after opening a connection if it needs a new one, and another thread
   may run first.  So a host can see a request less than the delay after the request
   before it, by up to the time that the earlier request took to reach the host, such
   as the time its new connection took to open.
"""

from dataclasses import dataclass, field
import hashlib
import json
from pathlib import Path
import random
import re
import threading
import time
from urllib.parse import quote, urlsplit, urlunsplit

import requests

_RETRYABLE_STATUS_CODES = (408, 429, 500, 502, 503, 504)

# The latest request start recorded for each host, by clock: see the module docstring.
# The readings of two clocks cannot be compared, so each monotonic_fun has its own
# record.
_REQUEST_STARTS_BY_CLOCK = {}
_REQUEST_STARTS_LOCK = threading.Lock()


class RobotsDisallowedError(RuntimeError):
    """Raised when robots.txt disallows a request."""


@dataclass(frozen=True)
class RetryConfig:
    """Retry behavior for transient HTTP failures."""

    max_attempts: int = 4
    first_backoff_s: float = 1.0
    max_backoff_s: float = 30.0
    retryable_status_codes: tuple[int, ...] = _RETRYABLE_STATUS_CODES


@dataclass(frozen=True)
class ThrottleConfig:
    """Per-host spacing of request starts, as the module docstring describes."""

    min_delay_s: float = 0.0
    mean_delay_s: float = 0.0

    def give_delay_s(self, expovariate_fun):
        """Return the next inter-request delay."""
        min_delay_s = max(self.min_delay_s, 0.0)
        mean_delay_s = max(self.mean_delay_s, 0.0)
        if mean_delay_s <= min_delay_s:
            return min_delay_s
        extra = expovariate_fun(1.0 / (mean_delay_s - min_delay_s))
        return min_delay_s + extra


@dataclass(frozen=True)
class CacheConfig:
    """On-disk cache for conditional GETs."""

    dir_path: str | None = None


@dataclass(frozen=True)
class PoliteDownloadConfig:
    """Configuration for polite HTTP downloads."""

    user_agent: str
    default_timeout_s: float = 30.0
    accept_language: str | None = None
    referer: str | None = None
    default_headers: dict[str, str] = field(default_factory=dict)
    throttle: ThrottleConfig = field(default_factory=ThrottleConfig)
    retry: RetryConfig = field(default_factory=RetryConfig)
    cache: CacheConfig = field(default_factory=CacheConfig)
    obey_robots_txt: bool = False
    # The user agent robots.txt is obeyed as, if not user_agent, for every request,
    # a redirect's hop to another host included.  The User-Agent header still sends
    # user_agent.
    robots_user_agent: str | None = None

    def give_robots_user_agent(self):
        """Return the user agent whose robots.txt group governs requests."""
        if self.robots_user_agent is None:
            return self.user_agent
        return self.robots_user_agent

    def give_base_headers(self):
        """Return the default headers for the downloader session."""
        headers = {"User-Agent": self.user_agent}
        if self.accept_language is not None:
            headers["Accept-Language"] = self.accept_language
        if self.referer is not None:
            headers["Referer"] = self.referer
        headers.update(self.default_headers)
        return headers


@dataclass(frozen=True)
class DownloadResult:
    """Binary download result with encoding metadata."""

    body: bytes
    encoding: str | None
    final_url: str


@dataclass(frozen=True)
class _CacheEntry:
    body: bytes
    encoding: str | None
    etag: str | None
    last_modified: str | None
    final_url: str


class PoliteDownloader:
    """HTTP client with throttling, retries, caching, and robots checks.

    The throttle spaces requests as the module docstring says.  A test can replace the
    clock and the sleep with monotonic_fun and sleep_fun.
    """

    def __init__(
        self,
        config: PoliteDownloadConfig,
        session: requests.Session | None = None,
        sleep_fun=time.sleep,
        monotonic_fun=time.monotonic,
        expovariate_fun=random.expovariate,
    ):
        self._config = config
        self._session = session if session is not None else requests.Session()
        self._session.headers.update(config.give_base_headers())
        self._sleep_fun = sleep_fun
        self._monotonic_fun = monotonic_fun
        self._expovariate_fun = expovariate_fun
        self._robots_by_origin = {}

    def close(self):
        """Close the underlying HTTP session."""
        self._session.close()

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc, tb):
        self.close()
        return False

    def get_bytes(
        self,
        url,
        *,
        params=None,
        headers=None,
        timeout=None,
        allow_cache=True,
        obey_robots=None,
    ):
        """GET bytes from a URL."""
        return self._request(
            "GET",
            url,
            params=params,
            headers=headers,
            timeout=timeout,
            allow_cache=allow_cache,
            obey_robots=obey_robots,
        ).body

    def get_text(
        self,
        url,
        *,
        params=None,
        headers=None,
        timeout=None,
        allow_cache=True,
        obey_robots=None,
        encoding=None,
    ):
        """GET text from a URL."""
        result = self._request(
            "GET",
            url,
            params=params,
            headers=headers,
            timeout=timeout,
            allow_cache=allow_cache,
            obey_robots=obey_robots,
        )
        encoding = encoding or result.encoding or "utf-8"
        return result.body.decode(encoding)

    def get_json(
        self,
        url,
        *,
        params=None,
        headers=None,
        timeout=None,
        allow_cache=True,
        obey_robots=None,
        encoding=None,
    ):
        """GET JSON from a URL."""
        text = self.get_text(
            url,
            params=params,
            headers=headers,
            timeout=timeout,
            allow_cache=allow_cache,
            obey_robots=obey_robots,
            encoding=encoding,
        )
        return json.loads(text)

    def _request(
        self,
        method,
        url,
        *,
        params=None,
        headers=None,
        timeout=None,
        allow_cache=True,
        obey_robots=None,
    ):
        method = method.upper()
        timeout = self._config.default_timeout_s if timeout is None else timeout
        obey_robots = (
            self._config.obey_robots_txt if obey_robots is None else obey_robots
        )
        cache_entry = None
        prepared = self._prepare(method, url, params)
        prepared_url = prepared.url
        if method == "GET" and allow_cache:
            cache_entry = self._read_cache_entry(prepared_url)
        check_robots = method == "GET" and obey_robots
        if check_robots:
            self._assert_allowed_by_robots(prepared_url, prepared.path_url)
        attempts = max(self._config.retry.max_attempts, 1)
        for attempt in range(1, attempts + 1):
            request_headers = dict(headers or {})
            if cache_entry is not None:
                if cache_entry.etag is not None:
                    request_headers["If-None-Match"] = cache_entry.etag
                if cache_entry.last_modified is not None:
                    request_headers["If-Modified-Since"] = cache_entry.last_modified
            self._throttle(prepared_url)
            try:
                response = self._session.request(
                    method,
                    url,
                    params=params,
                    headers=request_headers or None,
                    timeout=timeout,
                    allow_redirects=False,
                )
                response = self._follow_redirects(response, timeout, check_robots)
            except (requests.ConnectionError, requests.Timeout):
                if attempt == attempts:
                    raise
                self._sleep_retry_backoff(attempt)
                continue
            if response.status_code == 304:
                if cache_entry is None:
                    raise RuntimeError(
                        f"Received 304 without cached content for {prepared_url}"
                    )
                return DownloadResult(
                    cache_entry.body,
                    cache_entry.encoding,
                    cache_entry.final_url,
                )
            if response.status_code in self._config.retry.retryable_status_codes:
                if attempt == attempts:
                    response.raise_for_status()
                self._sleep_retry_backoff(attempt)
                continue
            response.raise_for_status()
            result = DownloadResult(
                response.content,
                response.encoding or response.apparent_encoding,
                response.url,
            )
            if method == "GET" and allow_cache:
                self._write_cache_entry(
                    prepared_url, result, response.headers, newline=""
                )
            return result
        raise RuntimeError(f"Retry loop exhausted for {prepared_url}")

    def _follow_redirects(self, response, timeout, check_robots):
        """Return the response that ends response's chain of redirects.

        requests would follow the chain at once, inside the call that sent its first
        request.  Here each hop is the request that requests would send next,
        response.next, sent with the settings that Session.request would merge for it,
        once the throttle allows it and, if check_robots, once robots.txt allows its
        target.  The chain is limited to the session's max_redirects, as in requests.
        """
        hops = 0
        while (next_request := response.next) is not None:
            if hops == self._session.max_redirects:
                raise requests.TooManyRedirects(
                    f"Exceeded {hops} redirects.", response=response
                )
            hops += 1
            if check_robots:
                self._assert_allowed_by_robots(next_request.url, next_request.path_url)
            self._throttle(next_request.url)
            settings = self._session.merge_environment_settings(
                next_request.url, {}, None, None, None
            )
            response = self._session.send(
                next_request, allow_redirects=False, timeout=timeout, **settings
            )
        return response

    def _throttle(self, url):
        """Wait until a request to url's host may start, and record its start.

        It may start once this downloader's next delay has passed since the latest
        start recorded for that host on this downloader's clock.  Each start is
        recorded, even with no delay, since another downloader's delay may be longer.
        The clock is read again after each sleep, and the start recorded is that
        reading, so that a sleep that ends early or late cannot shorten the spacing.
        """
        delay_s = self._config.throttle.give_delay_s(self._expovariate_fun)
        host = urlsplit(url).hostname
        with _REQUEST_STARTS_LOCK:
            starts = _REQUEST_STARTS_BY_CLOCK.setdefault(self._monotonic_fun, {})
            now = self._monotonic_fun()
            if host in starts:
                due = starts[host] + delay_s
                while now < due:
                    self._sleep_fun(due - now)
                    now = self._monotonic_fun()
            starts[host] = now

    def _sleep_retry_backoff(self, attempt):
        retry = self._config.retry
        backoff_s = retry.first_backoff_s * (2 ** (attempt - 1))
        self._sleep_fun(min(backoff_s, retry.max_backoff_s))

    def _assert_allowed_by_robots(self, url, target):
        """Raise unless robots.txt allows target, the path and query a request
        for url sends."""
        parsed = urlsplit(url)
        origin = (parsed.scheme, parsed.netloc)
        groups = self._robots_by_origin.get(origin)
        if groups is None:
            groups = self._read_robots_groups(parsed.scheme, parsed.netloc)
            self._robots_by_origin[origin] = groups
        user_agent = self._config.give_robots_user_agent()
        if not _robots_allows(groups, user_agent, target):
            raise RobotsDisallowedError(f"robots.txt disallows {url} for {user_agent}")

    def _read_robots_groups(self, scheme, netloc):
        robots_url = urlunsplit((scheme, netloc, "/robots.txt", "", ""))
        timeout = self._config.default_timeout_s
        self._throttle(robots_url)
        response = self._session.request(
            "GET", robots_url, timeout=timeout, allow_redirects=False
        )
        # RFC 9309, section 2.3.1.2: a robots.txt read follows redirects, even to
        # another host, and the file they reach governs the authority first asked.
        # No robots.txt governs the redirects, as none governs the read itself.
        response = self._follow_redirects(response, timeout, check_robots=False)
        if response.status_code == 404:
            return {}
        response.raise_for_status()
        # RFC 9309, section 2.3: the file is UTF-8, whatever charset the response
        # declares.  surrogateescape keeps an invalid sequence's octets, as
        # urllib.robotparser.RobotFileParser.read does.
        text = response.content.decode("utf-8", "surrogateescape")
        return _parse_robots(text.splitlines())

    def _read_cache_entry(self, prepared_url):
        paths = self._cache_paths(prepared_url)
        if paths is None:
            return None
        meta_path, body_path = paths
        if not meta_path.exists() or not body_path.exists():
            return None
        with open(meta_path, encoding="utf-8") as meta_fp:
            meta = json.load(meta_fp)
        with open(body_path, "rb") as body_fp:
            body = body_fp.read()
        return _CacheEntry(
            body=body,
            encoding=meta.get("encoding"),
            etag=meta.get("etag"),
            last_modified=meta.get("last_modified"),
            final_url=meta["final_url"],
        )

    def _write_cache_entry(
        self, prepared_url, result, response_headers, newline: str = ""
    ):
        paths = self._cache_paths(prepared_url)
        if paths is None:
            return
        meta_path, body_path = paths
        meta_path.parent.mkdir(parents=True, exist_ok=True)
        meta = {
            "encoding": result.encoding,
            "etag": response_headers.get("ETag"),
            "final_url": result.final_url,
            "last_modified": response_headers.get("Last-Modified"),
        }
        with open(meta_path, "w", encoding="utf-8", newline=newline) as meta_fp:
            json.dump(meta, meta_fp, ensure_ascii=False, indent=2)
            meta_fp.write("\n")
        with open(body_path, "wb") as body_fp:
            body_fp.write(result.body)

    def _cache_paths(self, prepared_url):
        dir_path = self._config.cache.dir_path
        if dir_path is None:
            return None
        cache_dir = Path(dir_path)
        digest = hashlib.sha256(prepared_url.encode("utf-8")).hexdigest()
        return cache_dir / f"{digest}.json", cache_dir / f"{digest}.body"

    @staticmethod
    def _prepare(method, url, params):
        return requests.Request(method=method, url=url, params=params).prepare()


# The robots check implements RFC 9309's path matching itself.  In Python 3.13.15,
# urllib.robotparser.RobotFileParser percent-encodes "=" and "&" in a pattern with no
# "?", so that Disallow: /wiki/*action=edit never matches
# /wiki/index.php?title=X&action=edit; measures a match by the URL text it covers
# rather than by the rule; and decodes and re-encodes reserved characters, so that
# %2F matches "/".  Its grouping of lines and choice of a user agent's group are
# reproduced unchanged.

_URI_UNRESERVED = frozenset(
    "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-._~"
)
_PERCENT_ESCAPE = re.compile("%([0-9A-Fa-f]{2})?")


@dataclass(frozen=True)
class _RobotsRule:
    """An Allow or Disallow path in comparison form, split at its "*" wildcards."""

    allow: bool
    pieces: tuple[str, ...]
    anchored: bool
    octet_count: int

    @classmethod
    def from_path(cls, allow, path):
        """Make a rule from the path an Allow or Disallow line gives.

        A final "$" anchors the rule at the end of the target; any other "$" is a
        literal character.
        """
        anchored = path.endswith("$")
        if anchored:
            path = path[:-1]
        pieces = tuple(_robots_comparison_form(piece) for piece in path.split("*"))
        octet_count = len("*".join(pieces)) + (1 if anchored else 0)
        return cls(allow, pieces, anchored, octet_count)

    def matches(self, target):
        """Whether this rule matches target, a request target in comparison form.

        Each piece after the first is placed at its earliest occurrence, which
        leaves the most room for the pieces after it.
        """
        first, *rest = self.pieces
        if not target.startswith(first):
            return False
        position = len(first)
        if not rest:
            return not self.anchored or position == len(target)
        *middle, last = rest
        for piece in middle:
            position = target.find(piece, position)
            if position < 0:
                return False
            position += len(piece)
        if self.anchored:
            return len(target) - len(last) >= position and target.endswith(last)
        return target.find(last, position) >= 0


@dataclass(frozen=True)
class _RobotsGroup:
    """The user agents a group names, as written, and its rules, in file order."""

    user_agents: tuple[str, ...]
    rules: tuple[_RobotsRule, ...]


def _parse_robots(lines):
    """Return a robots.txt file's groups, keyed by lowercase user agent.

    Lines form groups, and groups naming the same user agent merge, exactly as in
    RobotFileParser.parse.  An Allow or Disallow line with an empty path still ends
    a group's user agents, but matches nothing.
    """
    groups = {}
    user_agents = []
    rules = []
    state = "start"  # then "user-agent" after a User-agent line, "rules" after a rule
    for line in lines:
        key, colon, value = line.split("#", 1)[0].strip().partition(":")
        if not colon:
            continue
        key = key.strip().lower()
        value = value.strip()
        if key == "user-agent":
            if state == "rules":
                _add_robots_group(groups, user_agents, rules)
                user_agents, rules = [], []
            user_agents.append(value)
            state = "user-agent"
        elif key in ("allow", "disallow"):
            if state != "start":
                state = "rules"
                if value:
                    rules.append(_RobotsRule.from_path(key == "allow", value))
        elif key in ("crawl-delay", "request-rate"):
            if state != "start":
                state = "rules"
        # A Sitemap line or an unrecognized line leaves the grouping alone.
    if state != "start":
        _add_robots_group(groups, user_agents, rules)
    return groups


def _add_robots_group(groups, user_agents, rules):
    group = _RobotsGroup(tuple(user_agents), tuple(rules))
    for user_agent in group.user_agents:
        key = user_agent.lower()
        earlier = groups.get(key)
        if earlier is None:
            groups[key] = group
            continue
        # As urllib.robotparser.merge_entries: the user agents both groups name,
        # spelled and ordered as in the earlier, and its rules before the later's.
        groups[key] = _RobotsGroup(
            tuple(a for a in earlier.user_agents if a in group.user_agents),
            earlier.rules + group.rules,
        )


def _select_robots_group(groups, user_agent):
    """Return the group RobotFileParser chooses for user_agent, or None.

    First the group named by the whole user agent string; then the first group
    naming, other than as "*", a substring of its product token; then the "*" group.
    """
    group = groups.get(user_agent.lower())
    if group is not None:
        return group
    product = user_agent.split("/")[0].lower()
    for group in groups.values():
        for agent in group.user_agents:
            if agent != "*" and agent.lower() in product:
                return group
    return groups.get("*")


def _robots_allows(groups, user_agent, target):
    """Whether robots.txt allows user_agent to request target.

    target is the path and query a request sends.  Of the rules in user_agent's
    group that match it, the one with the most octets decides, and an Allow wins a
    tie (RFC 9309, section 2.2.2).  A target that no rule matches is allowed, as is
    every target when no group applies, and /robots.txt itself.
    """
    if target == "/robots.txt":
        return True
    group = _select_robots_group(groups, user_agent)
    if group is None:
        return True
    target = _robots_comparison_form(target)
    decisive = max(
        (
            (rule.octet_count, rule.allow)
            for rule in group.rules
            if rule.matches(target)
        ),
        default=(0, True),
    )
    return decisive[1]


def _robots_comparison_form(text):
    """Return text percent-encoded as requests prepares a request target.

    Characters other than the unreserved ones, the sub-delimiters, ":", "@", "/"
    and "?" are encoded as their UTF-8 octets; an escape of an unreserved character
    is decoded and any other escape uppercased (RFC 3986, section 6.2.2); and a "%"
    that begins no escape is encoded.  The sub-delimiters "*" and "$" are encoded
    too, so that a rule's %2A and %24 match them (RFC 9309, section 2.2.3).
    """
    encoded = quote(text, safe="!&'()+,;=:@/?%", errors="surrogateescape")
    return _PERCENT_ESCAPE.sub(_normalize_percent_escape, encoded)


def _normalize_percent_escape(match):
    hex_digits = match.group(1)
    if hex_digits is None:
        return "%25"
    char = chr(int(hex_digits, 16))
    if char in _URI_UNRESERVED:
        return char
    return "%" + hex_digits.upper()
